package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import android.opengl.*;import java.io.*;import java.nio.*;import java.nio.file.*;import org.json.*;
public final class SkySceneGpuInstrumentation extends SceneGpuInstrumentation {
 long pixelsChecked,geometryPixels,visibleSky,occludedSky;
 ByteBuffer read(int width,int height){ByteBuffer b=ByteBuffer.allocateDirect(width*height*4);GLES20.glReadPixels(0,0,width,height,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,b);ok(GLES20.glGetError()==0,"scene readback");return b;}
 String verify(NativeSkyScene frame,int width,int height,int active)throws Exception{int[] id={0};GLES20.glGenTextures(1,id,0);int tex=id[0];GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,tex);GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D,0,GLES20.GL_RGBA,width,height,0,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,null);GLES20.glGenFramebuffers(1,id,0);int fbo=id[0];GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,fbo);GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,tex,0);ok(GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER)==GLES20.GL_FRAMEBUFFER_COMPLETE,"scene target");ByteBuffer legacy,mask;
 try(NativeSceneGpu gpu=new NativeSceneGpu()){ok(gpu.draw(frame.scene,active,height)>0,"geometry missing");legacy=read(width,height);GLES20.glDisable(GLES20.GL_SCISSOR_TEST);GLES20.glClearColor(0,0,0,0);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);ok(gpu.drawOverBackground(frame.scene,active,height)>0,"over geometry missing");mask=read(width,height);}
 try(NativeSkySceneGpu gpu=new NativeSkySceneGpu()){ok(gpu.draw(frame,active,height)>0,"joined geometry missing");}ByteBuffer actual=read(width,height),sky=frame.exactRgba();for(int y=0;y<height;y++)for(int x=0;x<width;x++){int at=(y*width+x)*4,sy=Math.min(159,(int)((height-y-.5)*160/height)),sx=Math.min(239,(int)((x+.5)*240/active)),source=(sy*240+sx)*4;boolean g=(mask.get(at+3)&255)>127,s=x<active&&(sky.get(source+3)&255)>0;for(int c=0;c<4;c++){int oldExpected=c==3?255:g?mask.get(at+c)&255:0,newExpected=c==3?255:g?mask.get(at+c)&255:s?sky.get(source+c)&255:0;ok((legacy.get(at+c)&255)==oldExpected,"default clear regression");if((actual.get(at+c)&255)!=newExpected)throw new AssertionError("sky geometry order "+x+","+y+" channel "+c);}pixelsChecked++;if(g)geometryPixels++;if(s&&!g)visibleSky++;if(s&&g)occludedSky++;}
 String hash=digest(actual);GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,0);GLES20.glDeleteFramebuffers(1,new int[]{fbo},0);GLES20.glDeleteTextures(1,new int[]{tex},0);return hash;}
 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{File dir=new File(getTargetContext().getFilesDir(),"sky-scene-fixtures");SkySceneTest.main(new String[]{dir.getPath()});startGl();live=true;JSONArray frames=new JSONArray();for(String kind:new String[]{"whole","split"}){NativeSkyScene frame=new NativeSkyScene(Files.readAllBytes(new File(dir,"sky-scene-"+kind+".nsb").toPath()));JSONObject row=new JSONObject();row.put("kind",kind);row.put("native_sha256",verify(frame,240,160,240));row.put("four_k_sha256",verify(frame,3840,2160,3240));frames.put(row);}endGl();live=false;startGl();live=true;NativeSkyScene retained=new NativeSkyScene(Files.readAllBytes(new File(dir,"sky-scene-whole.nsb").toPath()));ok(verify(retained,240,160,240).equals(frames.getJSONObject(0).getString("native_sha256")),"context recreation");ok(visibleSky>0&&occludedSky>0&&geometryPixels>0,"scene coverage geometry="+geometryPixels+" visibleSky="+visibleSky+" occludedSky="+occludedSky);JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_SKY_GEOMETRY_GPU");report.put("pixel_checks",pixelsChecked);report.put("geometry_samples",geometryPixels);report.put("visible_sky_samples",visibleSky);report.put("occluded_sky_samples",occludedSky);report.put("frames",frames);report.put("context_recreated",true);report.put("renderer",renderer);report.put("hud_included",false);report.put("initial_background_complete",false);report.put("game_steps",0);try(FileOutputStream out=getTargetContext().openFileOutput("sky-scene-gpu-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);}catch(Throwable e){android.util.Log.e("NFSUGSkySceneGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}

